		if (m_presence != 0) { return true; }
		if (m_OrdAllocGrp.hasAnySet()) { return true; }
		if (m_ExecAllocGrp.hasAnySet()) { return true; }
		if (m_Instrument.hasAnySet()) { return true; }
		if (m_InstrumentExtension.hasAnySet()) { return true; }
